// Guidance choices never change nomination. Optional checkpoints enter explicit encrypted saves only.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const COACH_SOURCE='https://www.sebi.gov.in/sebi_data/attachdocs/jun-2026/1780397706130.pdf';
export function coachRoute(a={}){if(a.holderDeceased===true||a.deceased===true)return 'deceased';if(a.type==='bank')return 'bank';if(a.type==='mf'&&a.mfMode==='demat')return 'demat-linked';if(a.type==='mf'&&a.mfMode!=='folio')return 'unknown';return ['demat','mf'].includes(a.type)?'securities':'unknown';}
export const coachContext=a=>JSON.stringify([a.id||'',a.type,a.mfMode,a.holding,a.product,a.nomination,a.review,a.institutionId,a.institution,coachRoute(a)]);
export function validateCoachCheckpoint(value=[],accounts=[]){
 if(!Array.isArray(value)||value.length>50)throw Error('invalidSave');
 const seen=new Set(),result=[];
 for(const item of value){
  if(!item||typeof item.accountId!=='string'||seen.has(item.accountId)||typeof item.context!=='string'||item.context.length>800)throw Error('invalidSave');
  seen.add(item.accountId);const a=accounts.find(a=>a.id===item.accountId);if(!a)throw Error('invalidSave');
  if(!Number.isInteger(item.step)||item.step<0||item.step>5||typeof item.correction!=='boolean'||typeof item.deceased!=='boolean')throw Error('invalidSave');
  for(const [key,choices] of [['minor',['','yes','no','unsure']],['example',['','holder','nominee']],['rights',['','yes','no']],['channel',['online','branch']],['reason',['','missing','wrong','unexplained']]])if(!choices.includes(item[key]))throw Error('invalidSave');
  // Account changes invalidate old learning; a checkpoint never authenticates a form or outcome.
  if(item.context!==coachContext(a))continue;
  result.push({accountId:a.id,context:item.context,step:item.step,minor:item.minor,example:item.example,rights:item.rights,channel:item.channel,reason:item.reason,correction:item.correction,deceased:item.deceased});
 }
 return result;
}
const button=(action,value,label)=>`<button type="button" class="secondary" data-coach-action="${action}" data-coach-value="${esc(value)}">${esc(label)}</button>`;
export function createNominationCoach(){
 const states=new Map();let active=null;
 function reset(){states.clear();active=null;}
 function handle(target){const el=target?.closest?.('[data-coach-action]');if(!el||!active)return false;const {coachAction:action,coachValue:value}=el.dataset;
  if(action==='claim-help'&&(active.deceased||active.route==='deceased'))return 'claim-help';
  if(action==='edit-context'&&(active.route==='unknown'||(active.step===4&&!['sole','joint'].includes(active.holding))))return 'edit-context';
  if(action==='deceased'){active.deceased=!active.deceased;active.error='';return true;}
  if(active.deceased||['deceased','unknown','demat-linked'].includes(active.route))return false;
  if(action==='channel'&&active.step===0&&['online','branch'].includes(value)){active.channel=value;active.error='';return true;}
  if(action==='correction'&&active.step===5&&active.correction&&['missing','wrong','unexplained'].includes(value)){active.reason=value;return true;}
  if(action==='example'&&active.step===2&&['holder','nominee'].includes(value)){active.example=value;active.error='';return true;}
  if(action==='rights'&&active.step===2&&['yes','no'].includes(value)){active.rights=value;active.error='';return true;}
  if(action==='help'){active.error=[
   'Use the institution named on your account statement. If someone sends you a form link, find the same nomination service through the institution’s official website or branch before using it.',
   'This field identifies your account, not the nominee. Find the reference on your statement or authenticated portal and compare it character by character with the official form. Do not paste it here.',
   'The holder owns the account; the nominee is the person the holder names in this request. For the relationship, read whose relationship the form asks for. The example above lets you try this distinction.',
   'Check a reliable date-of-birth record privately. If you cannot establish whether the institution treats the nominee as a minor, ask it before choosing an answer. Do not guess the birth date.',
   'Consent means the required holders agree to this request. Follow the institution’s own signature or authentication process. A helper must not sign for you or receive your OTP. If anything is unclear, pause before submitting.',
   '“Received” or “under processing” means the request is still awaiting an outcome. Look for a statement or message explicitly confirming nomination registration. If it asks for corrections, follow that correction route.'
  ][active.step];return true;}
  if(action==='record-blocked'&&active.step===5&&active.correction&&active.reason)return 'blocked';
  if(action==='back'&&active.step>0){if(active.step===5&&active.correction){active.correction=false;active.reason='';}else active.step--;active.error='';return true;}
  if(action==='minor'&&['yes','no','unsure'].includes(value)&&active.step===3){active.minor=value;active.error=value==='unsure'?'Check the nominee’s date of birth privately. Ask the institution whether its minor-nominee requirements apply, then return and choose Yes or No. Do not guess.':'';return true;}
  if(action==='next'&&active.step<5){if(active.step===2&&active.rights==='yes'){active.error='plainRightsWrong';return true;}if(active.step===2&&active.example==='holder'){active.error='The nominee is Tara. Try the example again before continuing.';return true;}if(active.step===4&&active.holding!=='sole'&&active.holding!=='joint'){active.error='Confirm whether the account is held solely or jointly, then update its account context before submission.';return true;}if(active.step===3&&(!active.minor||active.minor==='unsure')){active.error='Confirm whether your intended nominee is a minor with the institution before continuing.';return true;}active.step++;active.error='';return true;}
  if(action==='response'&&active.step===5){if(value==='choose'){active.correction=false;active.reason='';active.error='';return true;}if(value==='not-submitted'){active.step=4;active.error='';active.correction=false;active.reason='';return true;}if(value==='blocked'){active.correction=true;active.error='';return true;}if(['submitted','confirm'].includes(value))return value;if(value==='unsure'){active.error='Ask the institution what this response confirms. Keep the current account status unchanged until you can identify the outcome.';return true;}}
  return false;
 }
 function render(a={},guide={},t=key=>key){
  const route=coachRoute(a),key=coachContext(a);
  for(const old of states.keys())if(old!==key&&JSON.parse(old)[0]===(a.id||''))states.delete(old);
  if(!states.has(key)&&states.size>=50)states.delete(states.keys().next().value);
  if(!states.has(key))states.set(key,{step:0,minor:'',example:'',rights:'',channel:'online',reason:'',correction:false,error:'',deceased:false,route,holding:a.holding});active=states.get(key);
  const s=active,securities=route==='securities',stopped=s.deceased||route==='deceased';
  const text=key=>esc(t(key)),p=key=>`<p data-speak>${text(key)}</p>`,h=key=>`<h2 data-speak>${text(key)}</h2>`;
  const more=(body,key='plainRules')=>body?`<details class="step-explanation"><summary data-speak>${text(key)}</summary><div class="detail-body">${body}</div></details>`:'';
  let url='';try{const candidate=new URL(guide.url);if(candidate.protocol==='https:')url=candidate.href;}catch{}
  const providerHelp=guide.specific&&Array.isArray(guide.action)?`<details><summary>Steps for this institution</summary>${guide.scope?`<p>${esc(guide.scope)}</p>`:''}<ol>${guide.action.map(line=>`<li>${esc(line)}</li>`).join('')}</ol>${Array.isArray(guide.offline)&&guide.offline.length?`<p>Assisted or offline route:</p><ul>${guide.offline.map(line=>`<li>${esc(line)}</li>`).join('')}</ul>`:''}</details>`:'';
  const branchHelp=`<div class="coach-feedback"><h3>At the branch or service desk</h3><p>You can ask: “I want to check or update nomination for this account. Which form applies, what consent is needed, and what confirmation should I expect?”</p>${guide.scope?`<p>${esc(guide.scope)}</p>`:''}${Array.isArray(guide.offline)&&guide.offline.length?`<ol>${guide.offline.map(line=>`<li>${esc(line)}</li>`).join('')}</ol>`:'<p>Contact the institution’s official branch or service desk to confirm where this account is serviced and what to bring. Do not assume every branch can process it.</p>'}${securities?p('offlineSignatureHelp'):''}<p>Ask staff to explain unfamiliar fields before you sign. Keep your own acknowledgement and ask how to check the outcome.</p></div>`;
  const official=url&&guide.specific?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${guide.specific?'Open institution instructions':'Read regulatory guidance'}</a></p>${guide.formUrl?.startsWith('https://files.hdfcfund.com/')?`<p><a href="${esc(guide.formUrl)}" target="_blank" rel="noopener noreferrer">${text('plainFormTitle')} · PDF</a></p>`:''}`:`<h3>${text('plainQuestion')}</h3><blockquote data-speak>${text('plainFormQuestion')}</blockquote>`;
  let body='';
  if(stopped)body=`<h2>Get help after an account holder’s death</h2><p>If an account holder has died, contact the institution’s deceased-holder team. This nomination guide cannot determine entitlement or process that claim.</p>${button('claim-help','','Get help after a death')}`;
  else if(route==='demat-linked')body='<h2>Continue through the demat account</h2><p>These fund units are held in demat. Confirm the holding arrangement and use the linked demat account’s nomination route through its depository participant (DP), rather than a folio form.</p>';
  else if(route==='unknown')body=`<h2>Identify the account route first</h2><p>Ask the institution whether this is a bank deposit, demat account or mutual-fund folio. For mutual funds, confirm whether the units are held in demat before choosing a form.</p>${button('edit-context','','Update account details')}`;
  else if(s.step===0)body=h('plainFormTitle')+p('plainFormHelp')+`<div class="coach-options">${[['online','plainFormWeb'],['branch','plainFormDesk']].map(([value,key])=>button('channel',value,t(key)).replace('class="secondary"',`class="secondary" aria-pressed="${s.channel===value}"`)).join('')}</div>`+(s.channel==='branch'?'':official)+more((s.channel==='branch'?branchHelp:providerHelp), 'plainProvider')+more(`<p>${securities?(a.type==='demat'?'Use the nomination route for this demat account through its depository participant (DP).':'Use the nomination route for this mutual-fund folio through the AMC or its registrar and transfer agent (RTA).'):'Use your bank’s current nomination process for this deposit type. Banking rules are separate from securities rules.'}</p><p>First check whether a nomination already exists and whether you need to add or change it. Obtain the matching current form or authenticated online workflow.</p>${a.holding==='joint'?'<p>This is a joint account. Ask how all holders provide the required consent.</p>':a.holding!=='sole'?'<p>Confirm whether this account is sole or joint before choosing the submission route.</p>':''}`)+p('plainNotSent');
  else if(s.step===1)body=h('plainReferenceTitle')+p('plainReferenceHelp')+more('<p>Why: the institution needs to apply your request to the correct record. Match its requested format and check each character. Do not enter the reference in Virasat.</p>')+more(p('plainDematMeaning')+p('plainFolioMeaning'),'plainWords');
  else if(s.step===2)body=h('plainPersonTitle')+p('plainPersonHelp')+`<details ${s.example?'open':''}><summary data-speak>${text('plainPersonExample')}</summary>${p('plainPersonQuestion')}<div class="coach-options">${button('example','holder','Asha, the holder')}${button('example','nominee','Tara, the nominee')}</div>${s.example?`<p role="status">${s.example==='nominee'?'Correct. Tara is being nominated.':'Asha is the holder. The nominee field needs Tara’s name.'}</p>`:''}${s.example==='nominee'?p('plainRightsQuestion')+`<div class="coach-options">${button('rights','yes',t('plainMinorYes'))}${button('rights','no',t('plainMinorNo'))}</div>`+(s.rights&&s.error!=='plainRightsWrong'?p(s.rights==='no'?'plainRightsNo':'plainRightsWrong'):''):''}</details>`+more(`<p>${securities?'Enter the nominee’s accurate name and relationship to the account holder on the official form. These are mandatory nominee particulars under the cited securities framework.':'Follow the bank’s current form for the nominee’s particulars and relationship. Ask the bank to explain any uncertain field.'}</p>${securities?'<p>Contact details, share, identifier and guardian details are optional under the cited securities framework. Do not invent missing information; ask the institution to explain any conflicting requirement.</p>':''}`);
  else if(s.step===3)body=h('plainMinorTitle')+p('plainMinorHelp')+`<div class="coach-options">${[['yes','plainMinorYes'],['no','plainMinorNo'],['unsure','plainMinorUnsure']].map(([value,key])=>button('minor',value,t(key)).replace('class="secondary"',`class="secondary" aria-pressed="${s.minor===value}"`)).join('')}</div>`+(s.minor==='yes'?p(securities?'plainMinorSecurities':'plainMinorBank')+more(`<p>${securities?'Enter the minor nominee’s date of birth accurately in the official form’s requested format. It is mandatory for a minor nominee under this securities framework. Guardian details are optional under the cited framework; ask the institution to explain its current instructions.':'Ask the bank which date-of-birth and guardian particulars its current form requires for a minor nominee. Do not apply securities requirements to a bank deposit.'}</p>`)+more(p('plainGuardianMeaning'),'plainWords'):s.minor==='no'?'<p class="coach-feedback">You selected no minor nominee. Continue with the requirements that apply to your official form.</p>':'');
  else if(s.step===4&&a.holding!=='sole'&&a.holding!=='joint')body=`<h2>Is this account held alone or jointly?</h2><p>Ask whether the account is held solely or jointly and update its account context before submission. The required consent depends on this answer.</p>${button('edit-context','','Update account details')}`;
  else if(s.step===4)body=h('plainSubmitTitle')+p('plainSubmitHelp')+(a.holding==='joint'?p('plainJoint'):'')+p('plainPrivacy')+(s.channel==='branch'?'':official)+more((s.channel==='branch'?branchHelp:providerHelp),'plainProvider')+more(`<p>Review the particulars privately against your intended nomination. ${securities?'All joint holders must consent to a joint-account nomination.':'Ask the bank what consent applies to the holding arrangement.'} Follow the official channel’s signature or authentication instructions.</p>${securities?'<p>Check your statement-visibility choice: nominee names or a Yes/No status. A status indication alone does not verify the particulars.</p>':''}<p>Virasat does not send this request or check the completed form. Continue when you want help interpreting the institution’s response.</p>`);
  else body=h('plainResponseTitle')+(s.correction?'':p('plainResponseHelp')+`<div class="coach-options">${[['submitted','plainResponseReceived'],['blocked','plainResponseCorrection'],['confirm','plainResponseRegistered'],['unsure','plainResponseUnsure'],['not-submitted','plainResponseNotSent']].map(([v,k])=>button('response',v,t(k))).join('')}</div>`)+(s.correction?`<div class="coach-feedback">${p('plainCorrectionHelp')}<p>What reason did it give?</p><div class="coach-options">${[['missing','Missing information'],['wrong','Incorrect details'],['unexplained','No clear reason']].map(([value,label])=>button('correction',value,label).replace('class="secondary"',`class="secondary" aria-pressed="${s.reason===value}"`)).join('')}</div>${s.reason?`<p>${{missing:'Ask which exact field or document is missing and whether it is required for your account. Do not invent information.',wrong:'Ask which recorded detail differs and how to correct it through the official process. Check the corrected result privately.',unexplained:'Ask for the reason in writing, the exact next action and the official way to follow up.'}[s.reason]}</p>${button('record-blocked','',t('plainRecordCorrection'))}`:''}</div>`:'')+p('plainReceiptMeaning')+more('<p>A receipt establishes submission only. Registration confirmation may show status without nominee particulars; check only what the evidence supports.</p>');
  const canContinue=!stopped&&!['unknown','demat-linked'].includes(route);
  return `<section class="nomination-coach" lang="en" aria-labelledby="coach-title"><h1 id="coach-title" data-speak>${text('plainCoachTitle')}</h1><p class="coach-preview" data-speak>${text('plainCoachIntro')}</p>${canContinue?`<p class="coach-progress" data-coach-step="${s.step+1}">Step ${s.step+1} of 6</p>`:''}<div class="coach-content" tabindex="-1">${body}${s.error?`<p class="error" role="alert">${esc(s.error.startsWith('plain')?t(s.error):s.error)}</p>`:''}</div>${canContinue?`<div class="coach-navigation">${s.step?button('back','','Previous'):''}${s.step<5?button('next','',t(['plainContinueForm','plainContinueReference','plainContinuePerson','plainContinueMinor','plainContinueSubmit'][s.step])).replace('class="secondary"','class="primary"'):''}${button('help','',t('plainStepHelp'))}</div>`:''}${more(button('deceased','',s.deceased?'Return to nomination guidance':t('plainAfterDeath')), 'plainOtherHelp')}<details class="coach-source"><summary>Sources and boundaries</summary>${url&&!guide.specific?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Read regulatory guidance</a></p>`:''}<p>This guide neither submits nor verifies a nomination. It does not determine inheritance, ownership or investment suitability. No form particulars are collected here.</p><p>Securities source: <a href="${COACH_SOURCE}" target="_blank" rel="noopener noreferrer">SEBI circular of 29 May 2026</a>, sections 6, 7, 9.3, 10.1 and Annexure A, pages 6–7. Reviewed 4 October 2026; this does not verify an institution’s current workflow. Banking requirements are separate.</p></details></section>`;
 }
 function startResponse(a){render(a);if(!['unknown','demat-linked','deceased'].includes(active.route)&&!active.deceased){active.step=5;active.error='';return true;}return false;}
 function startCorrection(a){if(!startResponse(a))return false;active.correction=true;active.reason='';return true;}
 function snapshot(accounts){return validateCoachCheckpoint(accounts.flatMap(a=>{const context=coachContext(a),state=states.get(context);return state?[{accountId:a.id,context,...state}]:[]}),accounts);}
 function restore(value,accounts){const checked=validateCoachCheckpoint(value,accounts);reset();for(const item of checked){const a=accounts.find(a=>a.id===item.accountId);states.set(item.context,{...item,route:coachRoute(a),holding:a.holding,error:''});}}
 function navigate(value,a){for(const item of validateCoachCheckpoint(value,a?[a]:[]))states.set(item.context,{...item,route:coachRoute(a),holding:a.holding,error:''});}
 return {render,handle,reset,startResponse,startCorrection,snapshot,restore,navigate};
}
